"""JSONRPC client implementations."""

import asyncio
import dataclasses
import itertools
import logging
import typing

from jsilib import _utils
from jsilib.aio.interface import IReactor
from jsilib.jsi import exc as jsi_exc
from jsilib.jsi import helpers as jsi_helpers
from jsilib.jsi.interface import IJSIConnection, IJSIMessage

from . import _globals, exc
from .interface import IJSONRPCClient
from .messages import SID, JSONRPCMessage, JSONRPCNotif, JSONRPCRequest, JSONRPCResponse

__all__ = ['JSONRPCClient']

_next_subscriber_id = itertools.count(1)
_next_request_id = itertools.count(1)

logger = logging.getLogger(_globals.LOGGER_NAME)


class JSONRPCClient(IJSONRPCClient):
    """JSONRPC client implementation."""

    def __init__(self, reactor: IReactor, connection: IJSIConnection):

        @_utils.log_exceptions(logger)
        async def handle_connection():

            def handle_response(response: JSONRPCMessage[JSONRPCResponse]):
                self._requests_pending[response.head.id].notify(response)

            async def handle_notification(notif: JSONRPCMessage[JSONRPCNotif]):

                def matching_subscribers():
                    for subscriber in self._subscribers.values():
                        if subscriber.is_subscribed_to(notif.head):
                            yield subscriber

                async def trigger_subscriber_function(subscriber, cached):
                    body = await cached.acquire()
                    async with body:
                        await subscriber.func(JSONRPCMessage(notif.head, body=body))

                logger.debug('[%s] < %r', _utils.get_obj_addr(self), message)
                if notif.body.size() == 0:
                    for subscriber in matching_subscribers():
                        await subscriber.func(JSONRPCMessage(notif.head, body=notif.body))
                else:
                    cached = await jsi_helpers.create_cached_message(reactor, notif.body)
                    async with cached:
                        await asyncio.gather(*[trigger_subscriber_function(s, cached) for s in matching_subscribers()])

            while not self._connection.is_closed():
                try:
                    message = await JSONRPCMessage.load(await self._connection.recv())
                except jsi_exc.ConnectionClosedError:
                    self._reactor.run(self.close())
                else:
                    if isinstance(message.head, JSONRPCResponse):
                        handle_response(message)
                    elif isinstance(message.head, JSONRPCNotif):
                        await handle_notification(message)
                    else:
                        logger.warning(
                            '[%s] Got an unexpected message from server: %r (message ignored)',
                            _utils.get_obj_addr(self), message
                        )

        self._reactor = reactor
        self._connection = connection
        self._requests_pending = {}
        self._subscribers: typing.Dict[int, JSONRPCClient._Subscriber] = {}
        self._message_reader_task = reactor.run(handle_connection())
        self._closed = False

    def _raise_if_closed(self):
        if self._closed:
            raise exc.ClientClosedError()

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            logger.debug('[%s] Closing JSONRPC client...', _utils.get_obj_addr(self))
            await self._message_reader_task.cancel()
            while self._requests_pending:
                _, request = self._requests_pending.popitem()
                request.terminate()
            logger.info('[%s] JSONRPC client closed.', _utils.get_obj_addr(self))

    async def execute(self,
                      method: str,
                      params: typing.Any = None,
                      sid: SID = None,
                      body: IJSIMessage = None) -> JSONRPCMessage[JSONRPCResponse]:
        self._raise_if_closed()
        request_id = _utils.next_unique_id(JSONRPCRequest)
        request = JSONRPCMessage(JSONRPCRequest(id=request_id, method=method, params=params, sid=sid), body=body)
        logger.info(
            '[%s] Executing request: method=%r, params=%r, sid=%r, body=%r', _utils.get_obj_addr(self), method, params,
            sid, body
        )
        self._requests_pending[request_id] = pending_request = self._PendingRequest()
        await self._connection.send(request.dump())
        maybe_response = await pending_request.done()
        if maybe_response is None:
            raise exc.ClientClosedError()
        response = maybe_response
        del self._requests_pending[request_id]
        logger.info('[%s] Got response: %r', _utils.get_obj_addr(self), response)
        return response

    def subscribe(self, subscriber: typing.Coroutine, method: str, sid: SID = None) -> int:
        self._raise_if_closed()
        sub_id = _utils.next_unique_id(self.__class__._Subscriber)
        self._subscribers[sub_id] = tmp = self._Subscriber(subscriber, method, sid=sid)
        logger.info('[%s] Subscription created: %r (id: %d)', _utils.get_obj_addr(self), tmp, sub_id)
        return sub_id

    def unsubscribe(self, subscriber_id: int) -> bool:
        removed = self._subscribers.pop(subscriber_id, None) is not None
        if removed:
            logger.info('[%s] Subscription removed (id: %d)', _utils.get_obj_addr(self), subscriber_id)
        return removed

    class _PendingRequest:

        def __init__(self):
            self._sem = asyncio.Semaphore(0)

        def notify(self, response: JSONRPCResponse):
            self._response = response
            self._sem.release()

        def terminate(self):
            self._response = None
            self._sem.release()

        async def done(self) -> typing.Optional[JSONRPCResponse]:
            await self._sem.acquire()
            return self._response

    @dataclasses.dataclass
    class _Subscriber:
        func: typing.Coroutine
        method: str
        sid: typing.Optional[SID] = None

        def is_subscribed_to(self, notif: JSONRPCNotif) -> bool:
            return self.method == notif.method and\
                (self.sid is None or self.sid == notif.sid)
